"use client";

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import type { AxiosError } from "axios";

import { axiosConfig } from "@/lib/axios";
import { env } from "@/lib/env";
import type { ApiResponse, ApiResponseError } from "@/types/api";

const axios = axiosConfig(env.apiBaseUrl);

/**
 * Knowledge memos — markdown documents generated by the AI inside a knowledge
 * folder (project). Scoped under /workflow/knowledge/folders/{folder_id}/memos.
 */
const MEMOS_URL = (folderId: string) =>
  `${env.apiBaseUrl}/workflow/knowledge/folders/${folderId}/memos`;
const MEMO_URL = (folderId: string, memoId: string) =>
  `${MEMOS_URL(folderId)}/${memoId}`;

/** Memo item as returned by the list endpoint (no content). */
export interface KnowledgeMemo {
  id: string;
  knowledge_folder_id: string;
  title: string;
  revision: number;
  created_at: string;
  updated_at: string;
  created_by: string;
}

/** Full memo with markdown content (detail endpoint). */
export interface KnowledgeMemoDetail extends KnowledgeMemo {
  content: string;
}

export interface KnowledgeMemoListResponse {
  items: KnowledgeMemo[];
  next_page_token: string;
  total_count: number;
}

/** Body for POST (create) and PUT (update, adds expected_revision). */
export interface KnowledgeMemoWriteDto {
  title: string;
  content: string;
  /** Required on update — optimistic concurrency against `revision`. */
  expected_revision?: number;
}

export const knowledgeMemoKeys = {
  list: (folderId: string, search: string) =>
    ["getKnowledgeMemos", folderId, search] as const,
  detail: (folderId: string, memoId: string) =>
    ["getKnowledgeMemo", folderId, memoId] as const
};

/** GET /workflow/knowledge/folders/{folder_id}/memos */
export function useGetKnowledgeMemos(folderId: string | null, search = "") {
  return useQuery<ApiResponse<KnowledgeMemoListResponse>, AxiosError>({
    queryKey: knowledgeMemoKeys.list(folderId ?? "", search),
    enabled: Boolean(folderId),
    queryFn: async () =>
      (
        await axios.get<ApiResponse<KnowledgeMemoListResponse>>(
          MEMOS_URL(folderId!),
          { params: { page_size: 100, ...(search ? { search } : {}) } }
        )
      ).data,
    meta: { errorMessage: "Failed to load memos" }
  });
}

/** GET /workflow/knowledge/folders/{folder_id}/memos/{memo_id} */
export function useGetKnowledgeMemo(
  folderId: string | null,
  memoId: string | null
) {
  return useQuery<ApiResponse<KnowledgeMemoDetail>, AxiosError<ApiResponseError>>({
    queryKey: knowledgeMemoKeys.detail(folderId ?? "", memoId ?? ""),
    enabled: Boolean(folderId && memoId),
    queryFn: async () =>
      (
        await axios.get<ApiResponse<KnowledgeMemoDetail>>(
          MEMO_URL(folderId!, memoId!)
        )
      ).data,
    meta: { errorMessage: "Failed to load memo" }
  });
}

/** POST /workflow/knowledge/folders/{folder_id}/memos */
export function useCreateKnowledgeMemo(folderId: string | null) {
  const queryClient = useQueryClient();
  return useMutation<
    ApiResponse<KnowledgeMemo>,
    AxiosError<ApiResponseError>,
    KnowledgeMemoWriteDto
  >({
    mutationFn: async (payload) =>
      (
        await axios.post<ApiResponse<KnowledgeMemo>>(MEMOS_URL(folderId!), payload)
      ).data,
    onSuccess: () =>
      queryClient.invalidateQueries({
        queryKey: ["getKnowledgeMemos", folderId]
      }),
    meta: { errorMessage: "Failed to create memo" }
  });
}

/** PUT /workflow/knowledge/folders/{folder_id}/memos/{memo_id} */
export function useUpdateKnowledgeMemo(folderId: string | null) {
  const queryClient = useQueryClient();
  return useMutation<
    ApiResponse<KnowledgeMemo>,
    AxiosError<ApiResponseError>,
    { memoId: string } & KnowledgeMemoWriteDto
  >({
    mutationFn: async ({ memoId, ...payload }) =>
      (
        await axios.put<ApiResponse<KnowledgeMemo>>(
          MEMO_URL(folderId!, memoId),
          payload
        )
      ).data,
    onSuccess: (_, { memoId }) => {
      queryClient.invalidateQueries({
        queryKey: ["getKnowledgeMemos", folderId]
      });
      queryClient.invalidateQueries({
        queryKey: ["getKnowledgeMemo", folderId ?? "", memoId]
      });
    },
    meta: { errorMessage: "Failed to save memo" }
  });
}

/** DELETE /workflow/knowledge/folders/{folder_id}/memos/{memo_id} */
export function useDeleteKnowledgeMemo(folderId: string | null) {
  const queryClient = useQueryClient();
  return useMutation<ApiResponse<unknown>, AxiosError<ApiResponseError>, string>({
    mutationFn: async (memoId) =>
      (await axios.delete(MEMO_URL(folderId!, memoId))).data,
    onSuccess: () =>
      queryClient.invalidateQueries({
        queryKey: ["getKnowledgeMemos", folderId]
      }),
    meta: { errorMessage: "Failed to delete memo" }
  });
}
